    "objects_introduced": ["$DC$"]
  },
  {
    "role": "deduction",
    "text": "Therefore, since $DB$ is equal to $AC$, and $BC$ (is) common, the two sides $DB$, $BC$ are equal to the two sides $AC$, $CB$, respectively,",
    "assertion": "the two sides DB, BC equal the two sides AC, CB respectively",
    "spans": [
      { "label": "glue", "text": "Therefore, since " },
