      { "label": "assumption", "text": "$BC$ (is) common" },
      { "label": "glue", "text": ", " },
      { "label": "assertion", "text": "the two sides $DB$, $BC$ are equal to the two sides $AC$, $CB$, respectively" },
      { "label": "glue", "text": "," }
    ],
    "proof_cite": null
  },
